INSERT INTO ui.ui_surface_value (surface_name, name, label, description, value_type, always_available, typical_char_count, sort_order, auto_context, group_key) VALUES
('matrx-user/ai-results', 'selected_conversation_id', 'Selected conversation ID', 'UUID of the past conversation/run the user has selected. Empty when none is selected.', 'string', false, 36, 300, true, 'general'),
('matrx-user/ai-results', 'selected_conversation_title', 'Selected conversation title', 'Title of the selected past run. Empty when none is selected.', 'string', false, 80, 310, true, 'general'),
('matrx-user/ai-results', 'selected_conversation_agent_id', 'Selected run agent ID', 'UUID of the agent that produced the selected run. Empty when none is selected.', 'string', false, 36, 320, true, 'general'),
('matrx-user/ai-results', 'selected_conversation_agent_name', 'Selected run agent name', 'Name of the agent that produced the selected run. Empty when none is selected.', 'string', false, 60, 325, true, 'general'),
('matrx-user/ai-results', 'selected_conversation_message_count', 'Selected run message count', 'Number of messages in the selected run. Zero when none is selected.', 'number', false, 5, 330, true, 'general'),
('matrx-user/ai-results', 'selected_run_status', 'Selected run status', '"complete", "error", "cancelled", etc. — final status of the selected run. Empty when none is selected.', 'string', false, 12, 335, true, 'general'),
('matrx-user/ai-results', 'last_run_text', 'Last run output', 'Text of the final assistant message in the selected run. Empty when none is selected.', 'string', false, 2000, 340, true, 'general'),
('matrx-user/ai-results', 'agent_filter', 'Agent filter', 'Array of agent IDs the history view is currently filtered to. Empty array when unfiltered.', 'array', false, 200, 360, true, 'general'),
('matrx-user/ai-results', 'grouping_mode', 'Grouping mode', 'How the history list is currently grouped (e.g. "agent", "date", "none"). Empty when default.', 'string', false, 12, 365, true, 'general'),
('matrx-user/ai-results', 'search_query', 'Search query', 'Active history search string. Empty when the search box is blank.', 'string', false, 60, 370, true, 'general'),
('matrx-user/ai-results', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-user/ai-results', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-user/ai-results', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-user/ai-results', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-user/ai-results', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-user/education-audio-study', 'view', 'Current view', 'Which Audio Study view is open: "list" (the saved-studies home), "new" (the generation composer), "detail" (one study open — player or live run), or "review" (a live spoken quiz session). Always present when the surface emits at all — the read-only `/[id]/edit` access-gate route renders the same detail view and reports "detail".', 'string', true, 6, 300, true, 'tool_view'),
('matrx-user/education-audio-study', 'library_loaded', 'Library loaded', 'True once the saved audio studies have finished loading on the list view. False while still in flight — do not describe the library as empty until this is true. Absent on the other views.', 'boolean', false, 5, 300, true, 'audio_library'),
('matrx-user/education-audio-study', 'audio_count', 'Saved audio studies', 'How many audio studies the learner can see, after RLS filtering. 0 when the library is genuinely empty. Only present on the list view once loaded.', 'number', false, 3, 310, true, 'audio_library'),
('matrx-user/education-audio-study', 'audio_library', 'Audio library', 'Every saved audio study on the list view, as { id, title, format, source_title, status } — status is ''ready'' | ''error'' | in-progress. Empty array when the learner has none. Only present on the list view.', 'array', false, 900, 320, true, 'audio_library'),
('matrx-user/education-audio-study', 'request_source_kind', 'Source kind', 'Which source mode the composer is in: "deck" (build audio from one of the learner''s flashcard decks) or "topic" (build it from free text they type). Only present on the new view.', 'string', false, 5, 300, true, 'generation_request'),
('matrx-user/education-audio-study', 'request_deck_id', 'Selected deck', 'UUID of the flashcard deck the audio will be built from. Absent when the composer is in topic mode or no deck has been picked yet.', 'string', false, 36, 310, true, 'generation_request'),
('matrx-user/education-audio-study', 'request_topic', 'Topic', 'The free-text topic the learner typed to build audio from (e.g. "The causes of the French Revolution"). Absent in deck mode or while the box is still empty.', 'string', false, 60, 320, true, 'generation_request'),
('matrx-user/education-audio-study', 'request_format', 'Format', '"overview" (narrated walkthrough), "debate" (two opposing voices), or "panel" (multi-host roundtable). Always present on the new view — the composer opens on "overview" by default.', 'string', false, 8, 330, true, 'generation_request'),
('matrx-user/education-audio-study', 'request_host_count', 'Host count', 'How many voices the produced audio will use — 2 by default, 3-6 for a panel. Always present on the new view.', 'number', false, 1, 340, true, 'generation_request'),
('matrx-user/education-audio-study', 'request_adaptive', 'Target weak areas', 'True when the "target my weak areas" option is checked (deck mode only) — biases the produced audio toward concepts the learner has been struggling with, from FSRS study history. Always present in deck mode on the new view; meaningless in topic mode.', 'boolean', false, 5, 350, true, 'generation_request'),
('matrx-user/education-audio-study', 'generation_request', 'Generation request', 'The whole composer state as one object — source kind, the deck id or typed topic, format, host count, and the weak-areas toggle. The composite twin of the values above; present on the new view whenever any of them is.', 'object', false, 260, 360, true, 'generation_request'),
('matrx-user/education-audio-study', 'available_decks', 'Available decks', 'The flashcard decks offered in the composer''s deck picker, each with its id and name. Empty array when the learner has no decks; absent until the picker''s list has loaded. Only present on the new view.', 'array', false, 1200, 370, true, 'generation_request'),
('matrx-user/education-audio-study', 'record_loaded', 'Study loaded', 'True once the open audio study''s row has finished loading on the detail view. False while it is in flight or when the id is missing/denied — in which case the record values below are absent. Absent on the other views.', 'boolean', false, 5, 300, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_id', 'Audio study id', 'UUID of the audio study the learner has open (its `education.study_media` row id). Present on the detail view from the first render, before the row itself has loaded.', 'string', false, 36, 310, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_title', 'Audio study title', 'Title of the open audio study, as generated and stored. Absent until the row has loaded.', 'string', false, 60, 320, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_format', 'Format', '"overview", "debate", "panel", or "review" — the format this study was generated in. Absent until the row has loaded.', 'string', false, 8, 330, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_status', 'Study status', '"ready" once produced audio exists, "error" if generation failed, otherwise still generating. Absent until the row has loaded.', 'string', false, 9, 340, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_is_ready', 'Playback ready', 'True when a durable audio file (or a produced episode) exists and the ready player renders. False while a run is live/being recovered, in which case the page shows the streaming generation view instead. Absent until the row has loaded.', 'boolean', false, 5, 350, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_is_owner', 'Viewer owns this study', 'True when the current user owns the open audio study and therefore sees the regenerate / share / delete controls. False for a shared viewer listening to someone else''s audio. Absent until access has resolved.', 'boolean', false, 5, 360, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_source_kind', 'Built from', '"deck" or "topic" — what the open study was generated from. Absent until the row has loaded.', 'string', false, 5, 370, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_source_title', 'Source name', 'Human name of the deck or topic the open study was built from, shown as "from …" above the title. Absent when the stored row recorded no source title.', 'string', false, 50, 380, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_source_id', 'Source id', 'UUID of the deck the open study was built from. Absent for a free-text topic source, which has no record to point at.', 'string', false, 36, 390, false, 'audio_record'),
('matrx-user/education-audio-study', 'run_status', 'Live run status', 'The streaming generation run''s status when the study is not yet ready — "running", "error", or absent once `audio_is_ready` is true (the page renders the durable player instead). Absent on the ready path and until the row has loaded.', 'string', false, 8, 400, true, 'audio_record'),
('matrx-user/education-audio-study', 'audio_confidence', 'Grounding confidence', 'How well the open study is grounded in real source material — "grounded" when built from a deck with citations, "inferred" when built from a typed topic. Absent when the row carries no trust envelope.', 'string', false, 10, 300, true, 'audio_trust'),
('matrx-user/education-audio-study', 'audio_citations', 'Cited sources', 'The passages the open study is grounded in, from its stored trust envelope. Empty array for an inferred (topic-built) study. Derived evidence — never authored on this page.', 'array', false, 400, 310, false, 'audio_trust'),
('matrx-user/education-audio-study', 'review_phase', 'Review phase', '"setup" (picking a deck), "asking" (question read aloud), "answering" (learner speaking), "grading" (spoken answer being graded), "result" (verdict shown), or "summary" (session complete). No emitter mounts this surface on /education/audio-study/review yet, so this value is currently NEVER emitted at runtime — declared for when that gap closes.', 'string', false, 9, 300, true, 'review_session'),
('matrx-user/education-audio-study', 'review_deck_id', 'Review deck', 'UUID of the flashcard deck the live review session is drawing questions from. Not currently emitted — see review_phase.', 'string', false, 36, 310, true, 'review_session'),
('matrx-user/education-audio-study', 'review_card_index', 'Review progress', '0-based index of the card currently being asked, out of the session''s card count. Not currently emitted — see review_phase.', 'number', false, 2, 320, true, 'review_session'),
('matrx-user/education-audio-study', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-user/education-audio-study', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-user/education-audio-study', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-user/education-audio-study', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-user/education-audio-study', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-user/education-game', 'view', 'Current view', 'Which Study Games route the learner is on: "home" (the hub — streak, league, badges, and the three primary actions), "host" (the room-creation composer), "join" (the room-code entry), "solo" (a live single-player run), or "play" (a live multiplayer room). Always present when the surface emits at all — "solo" and "play" currently never emit (see manifest header).', 'string', true, 4, 300, true, 'tool_view'),
('matrx-user/education-game', 'host_source_kind', 'Room source kind', '"due" (the learner''s cross-deck due queue — the adaptive default) or "set" (one specific flashcard deck). Only present on the host view.', 'string', false, 3, 300, true, 'host_setup'),
('matrx-user/education-game', 'host_source_set_id', 'Selected deck', 'UUID of the flashcard deck picked as the room''s question source. Absent when host_source_kind is "due" or no deck has been picked yet.', 'string', false, 36, 310, true, 'host_setup'),
('matrx-user/education-game', 'host_source_set_name', 'Selected deck name', 'Name of the currently selected deck. Absent when host_source_kind is "due" or no deck is picked.', 'string', false, 40, 320, true, 'host_setup'),
('matrx-user/education-game', 'host_available_sets', 'Available decks', 'The learner''s flashcard decks offered in the host picker, each with id, name, and whether it is private (only the host can load its cards — a cross-account room needs a shared/public deck). Empty array when they have none; absent until the picker''s list has loaded. Only present on the host view.', 'array', false, 1200, 330, true, 'host_setup'),
('matrx-user/education-game', 'host_max_players', 'Max players', 'The room-size cap the room will be created with, from the education.game_room_size entitlement (shown before hosting, per the TRUST mandate — never a mid-workflow ambush). Always present on the host view.', 'number', false, 2, 340, true, 'host_setup'),
('matrx-user/education-game', 'host_creating', 'Creating room', 'True while the Create room button''s request is in flight. Absent on the other views.', 'boolean', false, 5, 350, true, 'host_setup'),
('matrx-user/education-game', 'join_code', 'Room code', 'The 5-character room code the learner has typed so far (uppercased as they type). Empty string before they type anything. Only present on the join view.', 'string', false, 5, 300, true, 'join_room'),
('matrx-user/education-game', 'join_error', 'Join error', 'The validation or lookup error shown under the code field — e.g. a too-short code or "No open room with that code." Absent whenever there is no error, which is the normal case.', 'string', false, 40, 310, true, 'join_room'),
('matrx-user/education-game', 'join_joining', 'Joining room', 'True while the room lookup is in flight. Absent on the other views.', 'boolean', false, 5, 320, true, 'join_room'),
('matrx-user/education-game', 'solo_source_set_id', 'Solo deck', 'UUID of the deck the solo-arcade run is drawing questions from, when launched with a ?set= deep link. Not currently emitted — see manifest header.', 'string', false, 36, 300, true, 'solo_session'),
('matrx-user/education-game', 'solo_score', 'Solo score', 'The learner''s running score in the live solo-arcade session. Not currently emitted — see manifest header.', 'number', false, 4, 310, true, 'solo_session'),
('matrx-user/education-game', 'room_id', 'Room id', 'UUID of the multiplayer room the learner is in on /education/game/play/[roomId]. Not currently emitted — see manifest header.', 'string', false, 36, 300, true, 'room_session'),
('matrx-user/education-game', 'room_phase', 'Room phase', 'Which stage the live room is in — lobby, playing, or results. Not currently emitted — see manifest header.', 'string', false, 7, 310, true, 'room_session'),
('matrx-user/education-game', 'room_player_count', 'Players in room', 'How many players are currently in the room (host + joiners), from Broadcast presence. Not currently emitted — see manifest header.', 'number', false, 2, 320, true, 'room_session'),
('matrx-user/education-game', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-user/education-game', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-user/education-game', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-user/education-game', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-user/education-game', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-user/education-learn', 'view', 'Current view', 'Which public reader page is open: "index" (the study-guide library at /education/learn) or "article" (one open guide at /education/learn/[...slug]). Declared for completeness; NOT currently emitted at runtime — see the manifest header.', 'string', false, 7, 300, true, 'reader_view'),
('matrx-user/education-learn', 'guide_count', 'Published guide count', 'How many study guides are published and listed on the index. Zero is possible before the first guide ships. Only meaningful on the index view.', 'number', false, 3, 300, true, 'guide_library'),
('matrx-user/education-learn', 'guide_library', 'Guide library', 'Every published study guide listed on the index, as { title, summary, href }, in the order the index server-computes them. Only meaningful on the index view.', 'array', false, 2000, 310, true, 'guide_library'),
('matrx-user/education-learn', 'article_slug', 'Guide slug', 'URL path of the open guide under /education/learn (may contain ''/'' for hierarchy, e.g. ''biology/cell-structure''). Only meaningful on the article view.', 'string', false, 30, 300, true, 'guide_article'),
('matrx-user/education-learn', 'article_title', 'Guide title', 'Headline of the open guide, rendered as the page''s <h1>. Only meaningful on the article view.', 'string', false, 60, 310, true, 'guide_article'),
('matrx-user/education-learn', 'article_summary', 'Guide summary', 'Short summary of the open guide, shown as the hero lede and used verbatim as the meta description. Only meaningful on the article view.', 'string', false, 200, 320, true, 'guide_article'),
('matrx-user/education-learn', 'article_subject', 'Guide subject', 'The subject slug the open guide belongs to (e.g. ''biology''), when set. Absent for a guide with no subject assigned.', 'string', false, 12, 330, true, 'guide_article'),
('matrx-user/education-learn', 'article_keywords', 'Guide keywords', 'SEO keywords stored on the open guide. Empty array when none were set.', 'array', false, 100, 340, true, 'guide_article'),
('matrx-user/education-learn', 'article_updated', 'Guide updated', 'The author-controlled content date shown to readers as ''Updated'', in YYYY-MM-DD form.', 'string', false, 10, 350, true, 'guide_article'),
('matrx-user/education-learn', 'article_sections', 'Guide body', 'The open guide''s article body — the full parsed EduSection[] the page renders (prose, feature-grid, steps, status-cards, stat-bar, faq, cta blocks). The whole content a visitor is reading. Large; bindable-only.', 'array', false, 6000, 360, false, 'guide_article'),
('matrx-user/education-learn', 'article_related', 'Related links', 'The open guide''s conversion cross-links — { tools?, subjects?, exams? } slug arrays — deciding which app tools and hub pages the page funnels the reader into.', 'object', false, 160, 370, true, 'guide_article'),
('matrx-user/education-learn', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-user/education-learn', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-user/education-learn', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-user/education-learn', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-user/education-learn', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-user/education-progress', 'view', 'Current view', 'Which Progress view is open: "dashboard" (the cross-mode analytics dashboard) or "learning_gain" (the pre/post learning-gain report). Always present.', 'string', true, 13, 300, true, 'progress_view'),
('matrx-user/education-progress', 'analytics_loading', 'Analytics loading', 'True while the cross-mode analytics are still being fetched/folded on the dashboard view. While true, the summary values below are absent. Absent on the learning_gain view.', 'boolean', false, 5, 300, true, 'analytics_summary'),
('matrx-user/education-progress', 'analytics_error', 'Analytics error', 'The error message shown when the analytics fetch failed. Absent on the happy path (the common case) and on the learning_gain view.', 'string', false, 80, 310, true, 'analytics_summary'),
('matrx-user/education-progress', 'analytics_has_data', 'Has data', 'True once the learner has studied enough for the analytics to be meaningful. False for a brand-new learner with an empty spine — in which case the numeric fields below are still present but all-zero, and no AI narrative is generated. Absent while loading and on the learning_gain view.', 'boolean', false, 5, 320, true, 'analytics_summary'),
('matrx-user/education-progress', 'overall_stats', 'Overall stats', 'The learner''s folded cross-mode totals as one object — { studied, mastered, learning, struggling, dueNow, totalAttempts, correctAttempts, accuracyPct, bestStreak }. accuracyPct is null when totalAttempts is 0. Absent while loading and on the learning_gain view.', 'object', false, 160, 330, true, 'analytics_summary'),
('matrx-user/education-progress', 'mode_stats', 'Stats by mode', 'Per-study-mode breakdown (flashcards, quizzes, practice tests, …), each the same shape as overall_stats plus { itemType, label }. Empty array for a mode the learner hasn''t tried. Absent while loading and on the learning_gain view.', 'array', false, 900, 340, true, 'analytics_summary'),
('matrx-user/education-progress', 'weak_topics', 'Weak topics', 'Per-topic breakdown for the topic-bearing mode (flashcards), weakest first — each { topic, count, masteryPct, struggling }. Empty array when there isn''t enough topic-tagged data yet. Absent while loading and on the learning_gain view.', 'array', false, 700, 350, true, 'analytics_summary'),
('matrx-user/education-progress', 'total_minutes', 'Total study minutes', 'Total minutes studied across all sessions and modes. Absent while loading and on the learning_gain view.', 'number', false, 4, 360, true, 'analytics_summary'),
('matrx-user/education-progress', 'session_count', 'Session count', 'Total number of study sessions recorded. Absent while loading and on the learning_gain view.', 'number', false, 3, 370, true, 'analytics_summary'),
('matrx-user/education-progress', 'current_streak', 'Current streak', 'Current daily study streak in days (from study_streak — distinct from any per-item mastery streak). Absent while loading and on the learning_gain view.', 'number', false, 3, 380, true, 'analytics_summary'),
('matrx-user/education-progress', 'accuracy_trend', 'Accuracy trend', 'How accuracy is moving week over week — { direction: "improving" | "flat" | "declining", recentPct, priorPct, weeks }. Absent when there isn''t enough history to compute a trend, while loading, and on the learning_gain view.', 'object', false, 90, 390, true, 'analytics_summary'),
('matrx-user/education-progress', 'gain_teaser_available', 'Learning-gain teaser available', 'True when the dashboard has a learning-gain report to tease (linking to the learning_gain view). Absent while loading and on the learning_gain view.', 'boolean', false, 5, 400, true, 'analytics_summary'),
('matrx-user/education-progress', 'narrative_loading', 'Narrative generating', 'True while the AI narrator is producing the headline/insights/recommendations. Absent on the learning_gain view. The dashboard auto-narrates once when analytics_has_data is true and overall_stats.studied is at least 3.', 'boolean', false, 5, 300, true, 'analytics_narrative'),
('matrx-user/education-progress', 'narrative_error', 'Narrative error', 'Error from the narration attempt, if any. Absent on the happy path — narration is optional chrome, so a failure here does not affect the numeric analytics. Absent on the learning_gain view.', 'string', false, 80, 310, true, 'analytics_narrative'),
('matrx-user/education-progress', 'narrative_headline', 'Narrative headline', 'The AI narrator''s one-line summary of the learner''s current standing. Absent before narration has run, while it is loading, on an error, and on the learning_gain view.', 'string', false, 90, 320, true, 'analytics_narrative'),
('matrx-user/education-progress', 'narrative_insights', 'Narrative insights', 'Grounded observations from the narrator, each { title, detail, severity: "good" | "watch" | "urgent" }. Absent under the same conditions as narrative_headline.', 'array', false, 600, 330, true, 'analytics_narrative'),
('matrx-user/education-progress', 'narrative_recommendations', 'Narrative recommendations', 'Prioritized next actions from the narrator, each { action, why, targetKind, topic }, where targetKind is one of "review" | "weak_area" | "learn" | "quiz" | "practice_test" or null. Absent under the same conditions as narrative_headline. This is the surface''s own best answer to "what should I study next" — read it before improvising a recommendation.', 'array', false, 500, 340, true, 'analytics_narrative'),
('matrx-user/education-progress', 'gain_loading', 'Report loading', 'True while the learning-gain report is still being fetched on the learning_gain view. Absent on the dashboard view.', 'boolean', false, 5, 300, true, 'gain_report'),
('matrx-user/education-progress', 'gain_error', 'Report error', 'Error message when the report failed to load. Absent on the happy path and on the dashboard view.', 'string', false, 80, 310, true, 'gain_report'),
('matrx-user/education-progress', 'gain_pairs', 'Baseline→post pairs', 'Every subject with a complete baseline+post measurement, each { subject, subjectLabel, baseline: {score, takenAt}, post: {score, takenAt}, delta, normalizedGain }. Empty array when the learner has no complete pairs yet (the report shows an empty state). Absent while loading and on the dashboard view.', 'array', false, 900, 320, true, 'gain_report'),
('matrx-user/education-progress', 'gain_overall_delta', 'Overall delta', 'Mean baseline→post score delta across all paired subjects (0..1, can be negative). Null when there are no complete pairs. Absent while loading and on the dashboard view.', 'number', false, 6, 330, true, 'gain_report'),
('matrx-user/education-progress', 'gain_overall_normalized', 'Overall normalized gain', 'Mean normalized gain (Hake''s g) across subjects where it''s defined (0..1) — the share of what was left to learn that was actually learned. Null when undefined for every subject. Absent while loading and on the dashboard view.', 'number', false, 6, 340, true, 'gain_report'),
('matrx-user/education-progress', 'gain_is_seed', 'Sample data', 'True when the report is showing SEED FIXTURES, not the learner''s real measurements — because the underlying P1 assessment-engine table isn''t live yet or the learner has no real pairs. When true, describe the numbers as illustrative, never as the learner''s actual results. Absent while loading and on the dashboard view.', 'boolean', false, 5, 350, true, 'gain_report'),
