('matrx-admin/users', 'user_count', 'Total user count', 'Number of accounts currently loaded from `/api/admin/users` into the table (before any client-side search/filter). Zero while the initial fetch is in flight or if it returns no rows.', 'number', true, 5, 100, true, 'roster'),
('matrx-admin/users', 'roster_sample', 'Roster sample', 'The first several loaded accounts, each with { id, email, display_name, admin_level, providers, email_confirmed, onboarding_completed, organizations }, for shape inspection. Bindable, not auto-context — live user PII. Empty array before the first successful load.', 'array', true, 2000, 110, false, 'roster'),
