('matrx-admin/knowledge', 'knowledge_section', 'Knowledge section', 'Which child of the Knowledge admin family is active: "cms_agents", "kg_cost", "kg_inspector", "podcasts_shows", "podcasts_show_detail", "podcasts_episode_detail", or "research_system". Always present — each emitter declares which one it is.', 'string', true, 20, 100, true, 'navigation'),
('matrx-admin/knowledge', 'cms_sites', 'CMS sites', 'Every client site (id, slug, name, domain, is_active, agent_write_policy, has_data_api_key) loaded on the CMS Agent Activity page. Present only on knowledge_section=cms_agents.', 'array', false, 2500, 200, false, 'cms_agents'),
('matrx-admin/knowledge', 'cms_activity_filter', 'CMS activity filter', 'The Activity tab''s current filter: { siteId, entityType, actor }, each ''all'' or a specific value. Present only on cms_agents.', 'object', false, 100, 210, true, 'cms_agents'),
