('matrx-admin/knowledge', 'cms_selected_site_id', 'CMS selected site', 'UUID of the site whose page tree/assets the Pages/Assets tabs show (defaults to the first loaded site). Present only on cms_agents.', 'string', false, 36, 225, true, 'cms_agents'),
('matrx-admin/knowledge', 'cms_site_pages', 'CMS site page tree', 'Pages of cms_selected_site_id (id, slug, route, title, category, page_type, is_published, has_draft, sort_order), grouped by category. Present only on cms_agents.', 'array', false, 4000, 230, false, 'cms_agents'),
('matrx-admin/knowledge', 'cms_pending_exceptions', 'CMS pending exceptions', 'Content-validation exceptions with status ''pending'' on the Approvals tab (id, rule_id, node_path, excerpt, fix_hint, severity, note). Present only on cms_agents; empty array when none are pending.', 'array', false, 2500, 235, false, 'cms_agents'),
('matrx-admin/knowledge', 'cms_selected_site_assets', 'CMS selected site assets', 'Media assets of cms_selected_site_id (id, file_name, file_type, mime_type, file_size, alt_text, folder, used_in_pages) on the Assets tab. Present only on cms_agents.', 'array', false, 3000, 240, false, 'cms_agents'),
('matrx-admin/knowledge', 'kg_cost_summary', 'KG cost summary', 'The dashboard''s six KPI tiles: spend_today_usd, spend_7d_usd, orgs_over_80pct, pending_batches, ner_coverage_pct, batch_savings_7d_usd. Present only on kg_cost.', 'object', false, 200, 300, true, 'kg_cost'),
('matrx-admin/knowledge', 'kg_cost_org_rows', 'KG cost org leaderboard', 'Per-org auto-RAG spend rows (organization_id, organization_name, daily_auto_rag_budget_usd, daily_auto_rag_cost_used_usd, percent_used, last_charge_at), up to 200. Present only on kg_cost.', 'array', false, 4000, 310, false, 'kg_cost'),
('matrx-admin/knowledge', 'kg_cost_batch_rows', 'KG cost pending batches', 'In-flight provider batch rows (id, provider, kind, organization_name, status, est_cost_usd, poll_count, next_poll_at), up to 100. Present only on kg_cost.', 'array', false, 3500, 320, false, 'kg_cost'),
('matrx-admin/knowledge', 'kg_cost_open_org_id', 'KG cost open org', 'organization_id of the org whose detail dialog is open. Absent when no org drill-down is open.', 'string', false, 36, 330, true, 'kg_cost'),
('matrx-admin/knowledge', 'kg_cost_org_detail', 'KG cost org detail', 'Detail payload for kg_cost_open_org_id: { budget_usd, used_today_usd, window_start, daily_series, top_sources, batch_summary } plus the org''s auto-RAG toggle state (enabled, indexNonPdf, suggestionSweeps). Absent when no org drill-down is open.', 'object', false, 1500, 335, true, 'kg_cost'),
('matrx-admin/knowledge', 'kg_cost_open_batch_id', 'KG cost open batch', 'id of the batch whose detail dialog is open. Absent when no batch drill-down is open.', 'string', false, 36, 340, true, 'kg_cost'),
('matrx-admin/knowledge', 'kg_cost_batch_detail', 'KG cost batch detail', 'Detail payload for kg_cost_open_batch_id: adds purpose, cost_usd, tokens_in, tokens_out, error, metadata, completed_at to the batch row. Absent when no batch drill-down is open.', 'object', false, 800, 345, true, 'kg_cost'),
('matrx-admin/knowledge', 'kg_inspector_tab', 'KG inspector tab', 'Which of the three tabs is active: "entities", "mentions", or "edges". Present only on kg_inspector.', 'string', false, 10, 400, true, 'kg_inspector'),
('matrx-admin/knowledge', 'kg_inspector_selected_entity', 'KG inspector selected entity', 'The entity the admin drilled into: { id, name, kind }. Drives the Mentions tab. Absent until an entity/edge endpoint is clicked.', 'object', false, 150, 405, true, 'kg_inspector'),
('matrx-admin/knowledge', 'kg_entities_filter', 'KG entities filter', 'Entities tab filter/sort state: { kind, q, page, sortKey, sortDir }. Present only when kg_inspector_tab is entities.', 'object', false, 150, 410, true, 'kg_inspector'),
('matrx-admin/knowledge', 'kg_entities', 'KG entities', 'Entity rows matching kg_entities_filter (id, kind, canonical_name, organization_id, mention_count, source_count, confidence_avg), up to 200. Present only when kg_inspector_tab is entities.', 'array', false, 6000, 415, false, 'kg_inspector'),
('matrx-admin/knowledge', 'kg_mentions', 'KG entity mentions', 'Source mentions of kg_inspector_selected_entity (chunk_id, source_kind, source_id, snippet, span_start, span_end, confidence), paginated. Present only when kg_inspector_tab is mentions.', 'array', false, 4000, 420, false, 'kg_inspector'),
('matrx-admin/knowledge', 'kg_edges_filter', 'KG edges filter', 'Edges tab filter/sort state: { orgId, edgeKind, sortKey, sortDir }. Present only when kg_inspector_tab is edges.', 'object', false, 100, 425, true, 'kg_inspector'),
('matrx-admin/knowledge', 'kg_edges', 'KG top edges', 'Graph edges matching kg_edges_filter (id, kind, src_name, src_kind, dst_name, dst_kind, weight), up to 200. Present only when kg_inspector_tab is edges.', 'array', false, 5000, 430, false, 'kg_inspector'),
('matrx-admin/knowledge', 'podcast_shows', 'Podcast shows', 'Every show (id, slug, title, author, is_published, created_at) loaded on the Shows list. Present only on podcasts_shows.', 'array', false, 3000, 500, false, 'podcasts'),
('matrx-admin/knowledge', 'podcast_shows_search', 'Podcast shows search', 'The Shows list''s search text (URL-persisted, filters title/slug/author/id client-side). Empty when unset. Present only on podcasts_shows.', 'string', false, 30, 505, true, 'podcasts'),
('matrx-admin/knowledge', 'podcast_current_show_id', 'Active show ID', 'UUID of the show open on a show-detail page, or "new" on the create form. Present only on podcasts_show_detail.', 'string', false, 36, 510, true, 'podcasts'),
