('matrx-admin/knowledge', 'podcast_current_show_episodes', 'Active show''s episodes', 'Episodes belonging to podcast_current_show_id (id, slug, title, episode_number, duration_seconds, is_published), newest data first. Present only on podcasts_show_detail; empty array before the first episode.', 'array', false, 3500, 520, false, 'podcasts'),
('matrx-admin/knowledge', 'podcast_active_panel', 'Podcast detail panel', '"show" (settings form) or "episodes" (episode list), URL-persisted sub-tab of the show detail page. Present only on podcasts_show_detail.', 'string', false, 10, 525, true, 'podcasts'),
('matrx-admin/knowledge', 'podcast_current_episode_id', 'Active episode ID', 'UUID of the episode open on the episode-detail page, or "new" on the create form. Present only on podcasts_episode_detail.', 'string', false, 36, 530, true, 'podcasts'),
('matrx-admin/knowledge', 'podcast_current_episode', 'Active episode', 'Full episode record: { id, show_id, title, description, audio_url, video_url, display_mode, episode_number, duration_seconds, speakers, script, chapters, is_published }. Absent when podcast_current_episode_id is "new" and nothing has been saved yet.', 'object', false, 4000, 535, false, 'podcasts'),
('matrx-admin/knowledge', 'research_admin_tab', 'Research admin tab', 'Which of the three tabs is active: "templates", "agents" (the agent-wiring dashboard), or "projects". Present only on research_system.', 'string', false, 10, 600, true, 'research_system'),
('matrx-admin/knowledge', 'research_templates', 'Research templates', 'Research templates (id, name, description, is_system, keyword_templates, default_tags, agent_config — the seven agent-role keys like page_summary_agent_id, research_report_agent_id — autonomy_level). Present only on research_system.', 'array', false, 6000, 610, false, 'research_system'),
('matrx-admin/knowledge', 'research_builtin_agents', 'Research builtin agents', 'Builtin agent id/name pairs used to resolve each agent_config slot to a readable name in the templates and agent-wiring views.', 'array', false, 1000, 615, false, 'research_system'),
('matrx-admin/knowledge', 'research_topics', 'Research topics/projects', 'Research topic rows on the Projects tab (id, name, status, template_id, autonomy_level, linked project id via association edge), up to 50. Present only on research_system.', 'array', false, 2500, 620, false, 'research_system'),
