('matrx-admin/kind-registry', 'kind_registry_section', 'Kind registry section', 'Which sub-route is active: "catalog" (list/board/export), "detail" (one kind''s [kind] page), or "build" (the agent-assisted builder). Always present — each emitter declares which one it is.', 'string', true, 8, 100, true, 'navigation'),
('matrx-admin/kind-registry', 'catalog_tab', 'Catalog tab', 'Which of the three catalog-page tabs is active: "catalog" (table), "board" (status board), or "export" (schema/reference-graph explorer). Present only on kind_registry_section=catalog.', 'string', false, 8, 200, true, 'catalog'),
('matrx-admin/kind-registry', 'kind_catalog_rows', 'Kind catalog rows', 'Every declared kind (kind, label, family, isActive, version, visibility, componentCount, surfaceCount, exampleCount, and per-asset-column status cells: definition/example/gate_structural/component/skill/content_block/surface). Present only on kind_registry_section=catalog.', 'array', false, 8000, 210, false, 'catalog'),
('matrx-admin/kind-registry', 'kind_catalog_totals', 'Kind catalog totals', 'Header summary counts: total kinds, active count, red findings count, yellow findings count, drifted-row count (live DB vs committed snapshot). Present only on kind_registry_section=catalog.', 'object', false, 150, 220, true, 'catalog'),
('matrx-admin/kind-registry', 'kind_catalog_facets', 'Kind catalog facets', 'Table facet filters: { activeFacet: "all"|"on"|"off", issueFacet: "all"|"red"|"drift" }. Present only when catalog_tab is "catalog".', 'object', false, 60, 230, true, 'catalog'),
('matrx-admin/kind-registry', 'current_kind', 'Active kind', 'The kind slug (content_ir.kind_definition.kind, e.g. "topic_ideas") shown on the [kind] detail page — this is a slug, not a UUID. Present only on kind_registry_section=detail.', 'string', false, 24, 300, true, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_tab', 'Kind detail tab', 'Which of the 7 detail tabs is active: "preview", "examples", "assets", "try-input", "gate", "schema", or "inputs". Present only on kind_registry_section=detail.', 'string', false, 10, 305, true, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_summary', 'Kind detail summary', 'Header fields for current_kind: { id, kind, label, isActive, version, visibility, updatedAt }. Present only on kind_registry_section=detail.', 'object', false, 250, 310, true, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_schema', 'Kind detail schema', 'The kind''s field data and emitted JSON Schema: { fieldData, emittedJsonSchema }. Shown on the Schema tab. Present only on kind_registry_section=detail; either half may be null if not yet defined.', 'object', false, 3000, 315, false, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_doctor_row', 'Kind detail doctor status', 'Per-asset-column status (definition/example/gate_structural/component/skill/content_block/surface) for current_kind, same shape as one kind_catalog_rows entry. Present only on kind_registry_section=detail.', 'object', false, 500, 320, false, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_components', 'Kind detail components', 'kind_component rows for current_kind (id, platform, role, componentKey, source, isActive, isDefault). Present only on kind_registry_section=detail; empty array if none are registered.', 'array', false, 800, 325, false, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_surfaces', 'Kind detail surfaces', 'kind_surface rows for current_kind (id, surfaceType, token, parserStrategy, streaming, isActive). Present only on kind_registry_section=detail; empty array if none are registered.', 'array', false, 600, 330, false, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_skills', 'Kind detail skills', 'Skills that teach current_kind (skill teaching summaries). Present only on kind_registry_section=detail; empty array if none teach this kind.', 'array', false, 600, 335, false, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_examples', 'Kind detail examples', 'kind_example rows for current_kind (id, label, description, is_canonical, source, validation_status, kind_version, updated_at) — the Examples tab. Present only on kind_registry_section=detail; empty array before the first example is added.', 'array', false, 2500, 340, false, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_detail_canonical_example_data', 'Kind detail canonical example data', 'The `data` payload of current_kind''s canonical example (falls back to the newest example when none is marked canonical). Used by the Preview tab. Absent when no examples exist yet.', 'object', false, 2000, 345, false, 'kind_detail'),
('matrx-admin/kind-registry', 'kind_builder_structure', 'Kind builder structure', 'The raw data structure the admin pasted into the builder (JSON, a row sample, or a free-text field list) — becomes the core of the kind_architect prompt. Empty string before anything is typed. Present only on kind_registry_section=build.', 'string', false, 800, 400, true, 'kind_builder'),
('matrx-admin/kind-registry', 'kind_builder_notes', 'Kind builder direction notes', 'Optional free-text notes on style, interaction, or agent-trigger behavior the admin wants baked into the new kind. Empty string when unset. Present only on kind_registry_section=build.', 'string', false, 300, 410, true, 'kind_builder'),
('matrx-admin/kind-registry', 'kind_builder_architect_agent_id', 'Kind architect agent ID', 'The resolved agent id for the content_ir.kind_architect slot that will run when the admin presses Start. Absent when the slot fails to resolve.', 'string', false, 36, 420, true, 'kind_builder'),
('matrx-admin/kind-registry', 'kind_builder_can_start', 'Kind builder can start', 'True when kind_builder_structure is non-empty AND the architect agent slot resolved — mirrors the page''s own Start-button enablement. Present only on kind_registry_section=build.', 'boolean', false, 5, 430, true, 'kind_builder'),
('matrx-admin/kind-registry', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/kind-registry', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/kind-registry', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/kind-registry', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/kind-registry', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/skills', 'skills_section', 'Skills admin mode', 'Which mode the skills admin page is in: "list" (browser), "detail" (viewing a skill), "create" (new skill form), "ingest", or "categories". Always present — each emitter declares which one it is.', 'string', true, 8, 100, true, 'navigation'),
('matrx-admin/skills', 'skills_list', 'Skills list', 'Every loaded skill (id, skillId, label, description, skillType, iconName, allowedTools, triggerPatterns, platformTargets, version, categoryId, isActive, isSystem, isPublic, sortOrder). Present on skills_section=list.', 'array', false, 8000, 200, false, 'skills_registry'),
('matrx-admin/skills', 'skills_stats', 'Skills stats', 'Summary counts over skills_list: { total, system, public, personal }. Present on skills_section=list.', 'object', false, 60, 210, true, 'skills_registry'),
('matrx-admin/skills', 'skills_search', 'Skills search', 'The browser''s search text, matched against label/skillId/description client-side. Empty string when unset. Present on skills_section=list.', 'string', false, 30, 220, true, 'skills_registry'),
('matrx-admin/skills', 'skills_scope_filter', 'Skills scope filter', '"all", "system", "public", or "personal" — the browser''s visibility filter. Present on skills_section=list.', 'string', false, 10, 230, true, 'skills_registry'),
('matrx-admin/skills', 'skills_category_filter', 'Skills category filter', 'The category id the browser is filtered to, or "all". Present on skills_section=list.', 'string', false, 36, 240, true, 'skills_registry'),
('matrx-admin/skills', 'selected_skill_id', 'Selected skill ID', 'id of the skill being viewed/edited, from ?open=<skillId> or a browser row click. Absent on skills_section=list before any selection, and on ingest/categories.', 'string', false, 36, 300, true, 'skill_selection'),
('matrx-admin/skills', 'selected_skill', 'Selected skill', 'The full saved skill record for selected_skill_id: { skillId, label, description, skillType, body, allowedTools, triggerPatterns, disableAutoInvocation, platformTargets, version, categoryId, isActive, isSystem, isPublic }. Absent when skills_section=create (nothing saved yet) or no skill is selected.', 'object', false, 3000, 310, true, 'skill_selection'),
('matrx-admin/skills', 'skill_categories', 'Skill categories', 'The full category tree (id, categoryKey, label, parentCategoryId, sortOrder, isActive, userId — null userId means a system category). Present on skills_section=categories, and used to label skills_list''s categoryId elsewhere.', 'array', false, 2500, 400, false, 'skill_categories'),
('matrx-admin/skills', 'ingest_paths_text', 'Ingest paths', 'The multiline textarea of filesystem paths (one per line, #-comments stripped) the admin is about to dry-run or apply. Empty string before anything is typed. Present on skills_section=ingest.', 'string', false, 200, 500, true, 'skill_ingest'),
('matrx-admin/skills', 'ingest_status', 'Ingest status', '"idle", "loading", "ready", or "error" — the state of the last dry-run/apply call. Present on skills_section=ingest.', 'string', false, 8, 510, true, 'skill_ingest'),
('matrx-admin/skills', 'ingest_report', 'Ingest report', 'The last dry-run or apply result: { parsed, created, updated, unchanged, errors, roots, skills: [{ skillId, sourcePath, category, status, id }] }. Absent before the first dry-run/apply of the session.', 'object', false, 3000, 520, false, 'skill_ingest'),
('matrx-admin/skills', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/skills', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/skills', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/skills', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/skills', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline')
